#!/usr/bin/env python3
from pathlib import Path
from urllib.parse import quote
import html as H
import re
import sys

root = Path(sys.argv[1] if len(sys.argv) > 1 else "_site")


def p(route: str) -> Path:
    return root / route.strip("/") / "index.html"


def set_head(route: str, title: str, desc: str) -> None:
    path = p(route)
    text = path.read_text(encoding="utf-8")
    et, ed = H.escape(title, quote=True), H.escape(desc, quote=True)
    text = re.sub(r'<title>.*?</title>', f'<title>{et}</title>', text, count=1, flags=re.S)
    for attr, key, value in (("name","description",ed),("property","og:title",et),("property","og:description",ed),("name","twitter:title",et),("name","twitter:description",ed)):
        pat = re.compile(rf'(<meta\s+content=")[^"]*("\s+{attr}="{re.escape(key)}"\s*/?>)', re.I)
        text = pat.sub(lambda m: m.group(1)+value+m.group(2), text, count=1)
    path.write_text(text, encoding="utf-8")


def replace_main(route: str, main: str) -> None:
    path = p(route)
    if not path.is_file():
        raise SystemExit(f"stage50 missing {route}")
    text = path.read_text(encoding="utf-8")
    text, n = re.subn(r'<main\b[^>]*id="main-content"[^>]*>.*?</main>', lambda _m: main, text, count=1, flags=re.S|re.I)
    if n != 1:
        raise SystemExit(f"stage50 main replace failed {route}")
    path.write_text(text, encoding="utf-8")

